const generated=process.argv.includes('--generated');
const artifact=path.resolve(process.argv.slice(2).find(arg=>!arg.startsWith('--'))||'artifacts/platform/wpforms-heldout'),temp=await mkdtemp(path.join(tmpdir(),'wpf-masks-'));let browser,server;const cases=[];
try{await cp(path.join(artifact,'project'),temp,{recursive:true});if(!generated)await refreshComponentScripts(temp);const captured=JSON.parse(await readFile(path.join(artifact,'captured-model.json'))),page=captured.pages.find(p=>p.route==='/project-note/'),contract=generated?JSON.parse(await readFile(path.join(temp,'forms.json'))).forms.find(f=>f.provider==='wpforms'&&f.route==='/project-note/'):extract(page.sourceHTML,page.url).sourceForms.find(f=>f.provider==='wpforms');contract.delivery={endpoint:'/counter-test',format:'multipart'};assert.equal(contract.fields.find(f=>f.type==='textarea').maxWords,12);const config=JSON.parse(await readFile(path.join(temp,'forms.json')));config.forms=config.forms.map(f=>f.id===contract.id?contract:f);await writeFile(path.join(temp,'forms.json'),JSON.stringify(config));await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});
 for(const width of [1440,390]){const tab=await browser.newPage({viewport:{width,height:844},reducedMotion:'reduce'});let posts=0;await tab.route('**/counter-test',r=>{posts++;return r.abort();});await tab.goto(server.url+'/project-note/',{waitUntil:'networkidle'});await tab.evaluate(()=>document.fonts.ready);const screenshot=path.join(artifact,'masks-candidate-'+width+'.png');await tab.screenshot({path:screenshot,fullPage:true,animations:'disabled'});const pixel=visualScore(await readFile(path.join('work/wpf-heldout','project-note-'+width+'.png')),await readFile(screenshot));assert.ok(pixel>=.99,'Closed form mismatch '+pixel);
 const masked=tab.locator('[data-cloner-input-mask]');assert.equal(await masked.count(),1);await masked.focus();await masked.pressSequentially('ab1234');assert.equal(await masked.inputValue(),'AB-1234');assert.equal(await masked.evaluate(e=>e.checkValidity()),true);await masked.press('ControlOrMeta+A');await masked.pressSequentially('xy12');assert.equal(await masked.evaluate(e=>e.checkValidity()),false);await masked.pressSequentially('34');assert.equal(await masked.inputValue(),'XY-1234');
 const counters=tab.locator('[data-cloner-text-counter]');assert.equal(await counters.count(),2);await tab.locator('textarea').fill('one two three');assert.equal(await counters.nth(1).textContent(),'3 of 12 max words.');await tab.locator('input[maxlength]').fill('Hello');assert.equal(await counters.nth(0).textContent(),'5 of 40 max characters.');await tab.locator('textarea').fill(Array(13).fill('word').join(' '));assert.equal(await tab.locator('textarea').evaluate(e=>e.checkValidity()),false);await tab.locator('form.wpforms-form').evaluate(f=>f.reset());await tab.waitForFunction(()=>[...document.querySelectorAll('[data-cloner-text-counter]')].every(e=>e.textContent.startsWith('0 of ')));assert.equal(posts,0);cases.push({width,pixel,maskTyping:true,incompleteRejected:true,counterUpdates:true,reset:true,overLimitRejected:true});await tab.close();}
 await writeFile(path.join(artifact,'masks-candidate-check.json'),JSON.stringify({candidateScripts:!generated,cases,sourceSubmissions:0,aiCalls:0},null,2));console.log(JSON.stringify({cases:cases.length,minimumPixel:Math.min(...cases.map(c=>c.pixel))}));
}finally{await browser?.close();await server?.close();await rm(temp,{recursive:true,force:true});}
